--
-- Name: add_grocery_item(text, uuid, numeric, text, public.category, public.grocery_source); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_grocery_item(p_label text, p_product_id uuid DEFAULT NULL::uuid, p_quantity numeric DEFAULT NULL::numeric, p_unit text DEFAULT NULL::text, p_category public.category DEFAULT 'other'::public.category, p_source public.grocery_source DEFAULT 'manual'::public.grocery_source) RETURNS public.grocery_items
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_household uuid := public.current_household_id();
  v_item public.grocery_items;
begin
  if v_household is null then
    raise exception 'no household' using errcode = 'P0001';
  end if;

  select * into v_item from public.grocery_items g
  where g.household_id = v_household
    and g.status = 'to_buy'
    and (
      (p_product_id is not null and g.product_id = p_product_id)
      or (p_product_id is null and g.product_id is null and lower(trim(g.label)) = lower(trim(p_label)))
    )
  order by g.created_at
  limit 1
  for update;

  if found then
    if p_quantity is not null and v_item.quantity is not null
       and coalesce(v_item.unit, '') = coalesce(p_unit, '') then
      v_item.quantity := v_item.quantity + p_quantity;
    elsif v_item.quantity is null and p_quantity is not null then
      v_item.quantity := p_quantity;
      v_item.unit := p_unit;
    end if;
    update public.grocery_items
      set quantity = v_item.quantity,
          unit = v_item.unit,
          -- Asked for by hand: the line no longer belongs to recipes only.
          source = case when p_source = 'manual' then 'manual'::public.grocery_source else source end
      where id = v_item.id
      returning * into v_item;
    return v_item;
  end if;

  insert into public.grocery_items (household_id, label, product_id, quantity, unit, category, source)
  values (v_household, trim(p_label), p_product_id, p_quantity, p_unit, coalesce(p_category, 'other'), coalesce(p_source, 'manual'))
  returning * into v_item;
  return v_item;
end;
$$;


--
-- Name: add_to_pantry(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_to_pantry(p_items jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_household uuid := public.current_household_id();
  v_item jsonb;
  v_product_id uuid;
  v_product public.products;
  v_expires date;
  v_count int := 0;
begin
  if v_household is null then
    raise exception 'no household' using errcode = 'P0001';
  end if;
  for v_item in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    -- Resolved before reading: a product created by ensure_product is not visible to the statement
    -- that created it.
    v_product_id := coalesce(
      nullif(v_item ->> 'product_id', '')::uuid,
      public.ensure_product(v_item ->> 'label', coalesce((v_item ->> 'category')::public.category, 'other'))
    );
    select * into v_product from public.products where id = v_product_id;
    continue when not found;
    v_expires := case
      when v_item ? 'expires_on' then (v_item ->> 'expires_on')::date
      when coalesce((v_item ->> 'dated')::boolean, false) and v_product.shelf_life_days is not null
        then current_date + v_product.shelf_life_days
      else null
    end;
    perform public.pantry_put(
      v_household,
      v_product.id,
      coalesce((v_item ->> 'zone')::public.zone, v_product.default_zone),
      (v_item ->> 'quantity')::numeric,
      nullif(v_item ->> 'unit', ''),
      v_expires,
      false
    );
    insert into public.pantry_events (household_id, product_id, label, delta, unit, reason)
    values (v_household, v_product.id, v_product.name_en, (v_item ->> 'quantity')::numeric, nullif(v_item ->> 'unit', ''), 'correction');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


