-- Name: client_errors_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_errors_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if (select count(*) from public.client_errors where user_id = new.user_id and created_at > now() - interval '1 hour') >= 30 then
    return null;
  end if;
  return new;
end;
$$;


--
-- Name: complete_shopping(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_shopping(p_put_away jsonb DEFAULT NULL::jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_household uuid := public.current_household_id();
  v_item record;
  v_product_id uuid;
  v_product public.products;
  v_choice jsonb;
  v_expires date;
  v_count int := 0;
begin
  if v_household is null then
    raise exception 'no household' using errcode = 'P0001';
  end if;

  for v_item in
    update public.grocery_items g
      set status = 'bought', bought_at = now()
      where g.household_id = v_household and g.status = 'in_cart'
      returning g.*
  loop
    v_count := v_count + 1;
    select e into v_choice
    from jsonb_array_elements(coalesce(p_put_away, '[]'::jsonb)) e
    where e ->> 'id' = v_item.id::text
    limit 1;

    -- Things the catalog doesn't know become the household's own products, so they are put away too.
    v_product_id := coalesce(v_item.product_id, public.ensure_product(v_item.label, v_item.category));
    select * into v_product from public.products where id = v_product_id;
    if v_item.product_id is null then
      update public.grocery_items set product_id = v_product.id where id = v_item.id;
    end if;

    insert into public.pantry_events (household_id, product_id, label, delta, unit, reason, ref_id)
    values (v_household, v_product.id, v_item.label, v_item.quantity, v_item.unit, 'purchase', v_item.id);

    v_expires := case
      when v_choice ? 'expires_on' then (v_choice ->> 'expires_on')::date
      when v_product.shelf_life_days is null then null
      else current_date + v_product.shelf_life_days
    end;
    perform public.pantry_put(v_household, v_product.id,
                              coalesce((v_choice ->> 'zone')::public.zone, v_product.default_zone),
                              v_item.quantity, v_item.unit, v_expires, true);
  end loop;

  return v_count;
end;
$$;


--
-- Name: cook_recipe(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cook_recipe(p_recipe_id uuid, p_servings integer DEFAULT NULL::integer) RETURNS TABLE(product_id uuid, label text, category public.category, used numeric, unit text, left_quantity numeric, left_level public.pantry_level, ran_out boolean, saved boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare
  v_household uuid := public.current_household_id();
  v_recipe public.recipes;
  v_servings int;
  v_ing record;
  v_stock public.pantry_items;
  v_need numeric;
  v_left numeric;
  v_level public.pantry_level;
begin
  if v_household is null then
    raise exception 'no household' using errcode = 'P0001';
  end if;
  select * into v_recipe from public.recipes r where r.id = p_recipe_id;
  if not found then
    raise exception 'recipe not found' using errcode = 'P0002';
  end if;
  v_servings := coalesce(p_servings,
                         (select h.default_servings from public.households h where h.id = v_household),
                         v_recipe.servings);

  -- Each product once, with what all its lines use together.
  for v_ing in
    select n.product_id as pid, n.quantity as qty, n.unit as ing_unit, p.name_en, p.category as cat
    from public.recipe_needs(v_recipe.id) n
    join public.products p on p.id = n.product_id
    where not public.is_always_have(v_household, p.id)
    order by n.first_position
  loop
    select * into v_stock from public.pantry_items s
    where s.household_id = v_household and s.product_id = v_ing.pid
      and public.pantry_row_at_home(s.level, s.quantity, s.expires_on)
    order by s.expires_on nulls last, s.updated_at
    limit 1
    for update;
    continue when not found;

    v_need := v_ing.qty * v_servings / v_recipe.servings;
    if v_need is not null and v_stock.quantity is not null
       and coalesce(nullif(v_stock.unit, ''), 'unit') = coalesce(nullif(v_ing.ing_unit, ''), 'unit') then
      v_left := greatest(v_stock.quantity - v_need, 0);
      v_level := greatest(
        coalesce(v_stock.level, 'full'),
        case
          when v_left = 0 then 'out'
          when v_left <= v_stock.quantity * 0.25 then 'low'
          when v_left <= v_stock.quantity * 0.6 then 'half'
          else 'full'
        end::public.pantry_level
      );
    else
      v_left := null;
      v_level := case coalesce(v_stock.level, 'full')
        when 'full' then 'half'::public.pantry_level
        when 'half' then 'low'::public.pantry_level
        else 'out'::public.pantry_level
      end;
    end if;

    update public.pantry_items s
      set quantity = case when v_level = 'out' then 0 else v_left end, level = v_level
      where s.id = v_stock.id;

    insert into public.pantry_events (household_id, product_id, label, delta, unit, reason, ref_id)
    values (v_household, v_ing.pid, v_ing.name_en, -v_need, v_ing.ing_unit, 'cook', v_recipe.id);

    if v_level = 'out' then
      perform public.add_grocery_item(v_ing.name_en, v_ing.pid, null, null, v_ing.cat, 'ran_out');
    end if;

    product_id := v_ing.pid;
    label := v_ing.name_en;
    category := v_ing.cat;
    used := v_need;
    unit := v_ing.ing_unit;
    left_quantity := case when v_level = 'out' then 0 else v_left end;
    left_level := v_level;
    ran_out := v_level = 'out';
    saved := v_stock.expires_on is not null and v_stock.expires_on <= public.use_soon_by();
    return next;
  end loop;

  delete from public.up_next u
  where u.id = (select o.id from public.up_next o
                where o.household_id = v_household and o.recipe_id = v_recipe.id
                order by o.created_at limit 1);
  update public.recipes r set last_cooked_at = now() where r.id = v_recipe.id;
end;
$$;


--
-- Name: create_household(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_household(p_name text DEFAULT 'Home'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_household uuid;
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '28000';
  end if;
  if public.current_household_id() is not null then
    raise exception 'already in a household' using errcode = 'P0001';
  end if;
  insert into public.households (name) values (coalesce(nullif(trim(p_name), ''), 'Home'))
  returning id into v_household;
  insert into public.profiles (id, household_id) values (auth.uid(), v_household)
  on conflict (id) do update set household_id = excluded.household_id;
  return v_household;
end;
$$;


--
-- Name: create_invite(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invite() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_household uuid := public.current_household_id();
  v_code text;
begin
  if v_household is null then
    raise exception 'no household' using errcode = 'P0001';
  end if;
  -- One code at a time.
  delete from public.invites where household_id = v_household;
  loop
    v_code := public.invite_code();
    begin
      insert into public.invites (code, household_id) values (v_code, v_household);
      return v_code;
    exception when unique_violation then
      -- try another code
    end;
  end loop;
end;
$$;


--
-- Name: default_zone_for(public.category); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.default_zone_for(p_category public.category) RETURNS public.zone
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_category in ('produce', 'meat', 'dairy') then 'fridge'::public.zone
    when p_category = 'frozen' then 'freezer'::public.zone
    else 'cupboard'::public.zone
  end
$$;


--
-- Name: dismiss_pantry_proposal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_pantry_proposal(p_proposal_id uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  update public.pantry_proposals set status = 'dismissed', decided_at = now()
  where id = p_proposal_id and status = 'pending'
$$;


--
-- Name: ensure_product(text, public.category); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_product(p_label text, p_category public.category DEFAULT 'other'::public.category) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_household uuid := public.current_household_id();
  v_name text := trim(p_label);
  v_id uuid;
begin
  if v_name = '' then
    raise exception 'empty product name' using errcode = '22023';
  end if;
  select id into v_id from public.products
  where (household_id = v_household or household_id is null) and lower(name_en) = lower(v_name)
  order by household_id nulls last
  limit 1;
  if found then
    return v_id;
  end if;
  insert into public.products (household_id, name_en, category, default_zone, unit_family)
  values (v_household, upper(left(v_name, 1)) || substr(v_name, 2), coalesce(p_category, 'other'),
          public.default_zone_for(coalesce(p_category, 'other')), 'count')
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: expire_stale_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_stale_jobs() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with expired as (
    update public.import_jobs j
      set status = 'failed',
          error = 'The recipe reader is busy right now. Try again in a few minutes.',
          error_code = 'aiBusy',
          stage = null,
          finished_at = now()
      from public.job_kinds k
      where k.kind = j.kind
        and k.expires_in_queue
        and j.created_by is not null
        and j.status = 'queued'
        and j.queued_at < now() - interval '20 minutes'
      returning 1
  )
  select count(*)::int from expired
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'name', split_part(new.email, '@', 1)))
  on conflict (id) do nothing;
  return new;
end;
$$;


--
-- Name: heading_of(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.heading_of(p_line text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare
  t text := btrim(regexp_replace(coalesce(p_line, ''), '\s+', ' ', 'g'));
  v_name text;
begin
  if t ~ '[:：]$' then
    v_name := t;
  else
    v_name := coalesce(
      substring(t from '^\[([^]]+)\]$'),
      substring(t from '^\{([^}]+)\}$'),
      substring(t from '^\*\*([^*]+)\*\*$'),
      substring(t from '^__([^_]+)__$'),
      substring(t from '^#{1,6} ?([^#]+)$'),
      substring(t from '^[-–—=]+ ?([^-–—=]+) ?[-–—=]+$'));
    -- "[1 cup]" is no part.
    if v_name is null or v_name ~ '[0-9]' then
      return null;
    end if;
  end if;
  v_name := btrim(regexp_replace(regexp_replace(v_name, '^[ #*•·–—-]+', ''), '[ :：]+$', ''));
  if v_name !~ '[[:alpha:]]' then
    return null;
  end if;
  return btrim(left(v_name, 60));
end;
$_$;


--
-- Name: import_job_rules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_job_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_person boolean := current_user in ('authenticated', 'anon');
begin
  if tg_op = 'INSERT' then
    if v_person then
      -- Only the input is the app's.
      new.status := 'queued';
      new.created_at := now();
      new.attempts := 0;
      new.started_at := null;
      new.finished_at := null;
      new.recipe_id := null;
      new.proposal_id := null;
      new.already_saved := false;
      new.result := null;
      new.draft := null;
      new.error := null;
      new.error_code := null;
      new.stage := null;
      new.stage_at := null;
      new.claimed_lane := null;
      new.platform := null;
    end if;
    if new.created_by is not null
       and exists (select 1 from public.job_kinds where kind = new.kind and counts_toward_quota) then
      perform public.take_job_slot(new.household_id, case when v_person then null else (new.created_at at time zone 'utc')::date end);
    end if;
    new.queued_at := now();
    return new;
  end if;

  if v_person then
    -- Try again is all a person may do: a failed job back in the queue (the column grants keep the rest out).
    if not (old.status = 'failed' and new.status = 'queued') or public.is_background_kind(old.kind) then
      raise exception 'Only a failed job can be tried again.' using errcode = '42501';
    end if;
    new.error := null;
    new.error_code := null;
    new.stage := null;
    new.stage_at := null;
    new.finished_at := null;
    if exists (select 1 from public.job_kinds where kind = old.kind and counts_toward_quota) then
      perform public.take_job_slot(old.household_id);
    end if;
  end if;
  if new.status = 'queued' and old.status is distinct from 'queued' then
    new.queued_at := now();
  end if;
  return new;
end;
$$;


--
-- Name: ingredient_availability(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingredient_availability(p_recipe_id uuid) RETURNS TABLE(ingredient_id uuid, at_home boolean, soon boolean, always_have boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select i.id,
         i.product_id is not null and public.pantry_has(r.household_id, i.product_id),
         coalesce((select min(s.expires_on) from public.pantry_items s
                   where s.household_id = r.household_id and s.product_id = i.product_id
                     and public.pantry_row_at_home(s.level, s.quantity, s.expires_on)
                  ) between current_date and public.use_soon_by(), false),
         i.product_id is not null and public.is_always_have(r.household_id, i.product_id)
  from public.recipe_ingredients i
  join public.recipes r on r.id = i.recipe_id
  where i.recipe_id = p_recipe_id
$$;


--
-- Name: ingredient_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingredient_label(p_raw text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare
  v text := coalesce(p_raw, '');
  c_amount constant text := '^[0-9½⅓⅔¼¾⅛⅜⅝⅞]+([.,/][0-9]+)?([[:space:]]*([~–—-]|to|a|o)[[:space:]]*[0-9½⅓⅔¼¾⅛⅜⅝⅞]+([.,/][0-9]+)?)?[[:space:]]*';
  c_unit constant text := '^(tbsps?|tbs|tablespoons?|tsps?|teaspoons?|cups?|g|grs?|grams?|kgs?|kilos?|ml|l|liters?|litres?|lbs?|pounds?|oz|ounces?|cans?|tins?|cloves?|pinch(es)?|slices?|bunch(es)?|packs?|packets?|pieces?|pcs?|cdas?|cditas?|cdtas?|cucharadas?|cucharaditas?|tazas?|latas?|dientes?|pizcas?|piezas?)\.?([[:space:]]+|$)';
begin
  v := regexp_replace(v, '\([^()]*\)', ' ', 'g');          -- notes in parentheses
  v := regexp_replace(v, '([0-9]),([0-9])', '\1.\2', 'g');  -- a decimal comma is not a prep note
  v := split_part(v, ',', 1);                                -- "1 thumb ginger, sliced"
  v := regexp_replace(v, '^[[:space:]*•·–—-]+', '');         -- list bullets
  for i in 1..3 loop                                         -- "1.4 kg / 3 lbs beef": amount, unit, slash, again
    v := regexp_replace(v, c_amount, '', 'i');
    v := regexp_replace(v, c_unit, '', 'i');
    v := regexp_replace(v, '^(/|of[[:space:]]|de[[:space:]]|d'')[[:space:]]*', '', 'i');
  end loop;
  v := regexp_replace(v, '[[:space:]]+(to taste|al gusto|optional|opcional|for serving|to serve|para servir)\.?$', '', 'i');
  v := btrim(regexp_replace(v, '[[:space:]]+', ' ', 'g'), ' .;:-');
  if v ~ '^[0-9[:space:].,/~½⅓⅔¼¾⅛⅜⅝⅞–—-]*$' then  -- only an amount was left (any script counts as a name)
    return null;
  end if;
  return upper(left(v, 1)) || substr(v, 2);
end;
$_$;


--
-- Name: invite_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invite_code() RETURNS text
    LANGUAGE sql
    AS $$
  -- Byte 6 holds the uuid's version and byte 8 its variant: skipped. 32 divides 256: every letter as likely.
  select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + get_byte(u.b, t.i) % 32, 1), '' order by t.n)
  from (select uuid_send(gen_random_uuid()) as b) u,
       unnest(array[0, 1, 2, 3, 4, 5, 7, 9, 10, 11]) with ordinality as t(i, n)
$$;


--
-- Name: is_always_have(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_always_have(p_household uuid, p_product uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select s.always_have from public.household_staples s where s.household_id = p_household and s.product_id = p_product),
    (select p.is_staple from public.products p where p.id = p_product),
    false
  )
$$;


--
-- Name: is_background_kind(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_background_kind(p_kind text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.job_kinds where kind = p_kind and lane = 'background')
$$;


--
-- Name: is_quick_kind(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_quick_kind(p_kind text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.job_kinds where kind = p_kind and lane = 'quick')
$$;


--
-- Name: is_unit_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_unit_code(p_unit text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select p_unit is null
      or p_unit in ('g', 'ml', 'unit', 'tbsp', 'tsp', 'cup', 'can', 'bunch', 'pack', 'clove', 'pinch', 'slice')
$$;


--
-- Name: is_vague_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_vague_name(p_name text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  with w as (
    select array_remove(regexp_split_to_array(lower(coalesce(p_name, '')), '[^a-z0-9]+'), '') as words
  ), lists as (
    select
      array['other', 'others', 'misc', 'miscellaneous', 'various', 'assorted', 'item', 'items', 'ingredient', 'ingredients',
            'food', 'foods', 'product', 'products', 'thing', 'things', 'stuff', 'grocery', 'groceries', 'unknown', 'none', 'null',
            'otro', 'otros', 'otra', 'otras', 'varios', 'producto', 'productos', 'autre', 'autres', 'divers', 'produit', 'produits'
      ]::text[] as placeholders,
      array['sauce', 'sauces', 'seasoning', 'seasonings', 'spice', 'spices', 'condiment', 'condiments', 'paste', 'pastes',
            'powder', 'powders', 'oil', 'oils', 'herb', 'herbs', 'vegetable', 'vegetables', 'veggie', 'veggies', 'mix', 'mixes',
            'garnish', 'garnishes', 'topping', 'toppings'
      ]::text[] as heads,
      array['spice mix', 'spice blend', 'seasoning mix', 'seasoning blend', 'n/a']::text[] as phrases
  )
  select cardinality(w.words) > 0 and (
           array_to_string(w.words, ' ') in (
             select array_to_string(array_remove(regexp_split_to_array(x, '[^a-z0-9]+'), ''), ' ') from unnest(l.phrases) x)
        or (cardinality(w.words) = 1 and w.words[1] = any (l.heads))
        or (w.words && l.placeholders and w.words <@ (l.placeholders || l.heads)))
  from w, lists l
$$;


--
-- Name: job_rank(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_rank(p_lane text, p_created_by uuid) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_lane = 'background' then 3
    when p_created_by is null then 2
    when p_lane = 'quick' then 0
    else 1
  end
$$;


--
-- Name: join_household(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_household(p_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_household uuid;
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '28000';
  end if;
  delete from public.join_attempts where user_id = auth.uid() and at < now() - interval '1 day';
  if (select count(*) from public.join_attempts where user_id = auth.uid() and at > now() - interval '1 hour') >= 10 then
    raise exception 'Too many tries. Wait an hour, or ask for a new code.' using errcode = 'P0001';
  end if;
  delete from public.invites
  where code = v_code and expires_at > now()
  returning household_id into v_household;
  if v_household is null then
    insert into public.join_attempts (user_id) values (auth.uid());
    return null;
  end if;
  insert into public.profiles (id, household_id) values (auth.uid(), v_household)
  on conflict (id) do update set household_id = excluded.household_id;
  return v_household;
end;
$$;


--
-- Name: mark_cooked(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_cooked(p_up_next_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_recipe uuid;
begin
  delete from public.up_next where id = p_up_next_id returning recipe_id into v_recipe;
  if v_recipe is not null then
    update public.recipes set last_cooked_at = now() where id = v_recipe;
  end if;
end;
$$;


--
-- Name: mark_have(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_have(p_item_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_item public.grocery_items;
  v_product uuid;
begin
  update public.grocery_items set status = 'removed'
  where id = p_item_id and status in ('to_buy', 'in_cart')
  returning * into v_item;
  if not found then
    return;
  end if;
  v_product := coalesce(v_item.product_id, public.ensure_product(v_item.label, v_item.category));
  insert into public.pantry_events (household_id, product_id, label, delta, unit, reason, ref_id)
  values (v_item.household_id, v_product, v_item.label, null, null, 'have', v_item.id);
  perform public.pantry_put(v_item.household_id, v_product,
                            (select default_zone from public.products where id = v_product), null, null, null, false);
end;
$$;


--
-- Name: pantry_has(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pantry_has(p_household uuid, p_product uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (
           select 1 from public.pantry_items s
           where s.household_id = p_household and s.product_id = p_product
             and public.pantry_row_at_home(s.level, s.quantity, s.expires_on)
         )
      or (public.is_always_have(p_household, p_product)
          and not exists (
            select 1 from public.pantry_items s
            where s.household_id = p_household and s.product_id = p_product
              and (s.level = 'out' or s.quantity = 0)
          ))
$$;


--
-- Name: pantry_out(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pantry_out(p_product uuid, p_add_to_list boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_household uuid := public.current_household_id();
  v_product public.products;
  v_item public.grocery_items;
begin
  if v_household is null then
    raise exception 'no household' using errcode = 'P0001';
  end if;
  select * into v_product from public.products where id = p_product;
  if not found then
    raise exception 'product not found' using errcode = 'P0002';
  end if;
  update public.pantry_items set level = 'out', quantity = 0
  where household_id = v_household and product_id = p_product;
  if not found then
    insert into public.pantry_items (household_id, product_id, zone, quantity, level)
    values (v_household, p_product, v_product.default_zone, 0, 'out');
  end if;
  insert into public.pantry_events (household_id, product_id, label, delta, unit, reason)
  values (v_household, p_product, v_product.name_en, null, null, 'correction');
  if not p_add_to_list then
    return null;
  end if;
  v_item := public.add_grocery_item(v_product.name_en, p_product, null, null, v_product.category, 'ran_out');
  return v_item.id;
end;
$$;


--
-- Name: pantry_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pantry_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    household_id uuid DEFAULT public.current_household_id() NOT NULL,
    product_id uuid NOT NULL,
    zone public.zone NOT NULL,
    quantity numeric,
    unit text,
    level public.pantry_level,
    expires_on date,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: pantry_put(uuid, uuid, public.zone, numeric, text, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pantry_put(p_household uuid, p_product uuid, p_zone public.zone, p_quantity numeric, p_unit text, p_expires_on date, p_fresh boolean) RETURNS public.pantry_items
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_row public.pantry_items;
begin
  insert into public.pantry_items as cur (household_id, product_id, zone, quantity, unit, level, expires_on)
  values (p_household, p_product, p_zone, p_quantity, p_unit, 'full', p_expires_on)
  on conflict (household_id, product_id, zone) do update set
    quantity = case
      when not public.pantry_row_at_home(cur.level, cur.quantity, cur.expires_on) then excluded.quantity
      when cur.quantity is not null and excluded.quantity is not null
           and coalesce(cur.unit, '') = coalesce(excluded.unit, '') then cur.quantity + excluded.quantity
      when excluded.quantity is null and not p_fresh then cur.quantity
      else excluded.quantity
    end,
    unit = case
      when not public.pantry_row_at_home(cur.level, cur.quantity, cur.expires_on) then excluded.unit
      when cur.quantity is not null and excluded.quantity is not null
           and coalesce(cur.unit, '') = coalesce(excluded.unit, '') then cur.unit
      when excluded.quantity is null and not p_fresh then cur.unit
      else excluded.unit
    end,
    level = 'full',
    expires_on = case
      when p_fresh or not public.pantry_row_at_home(cur.level, cur.quantity, cur.expires_on) then excluded.expires_on
      else coalesce(cur.expires_on, excluded.expires_on)
    end
  returning * into v_row;
  return v_row;
end;
$$;


--
-- Name: pantry_row_at_home(public.pantry_level, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pantry_row_at_home(p_level public.pantry_level, p_quantity numeric, p_expires_on date) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select p_level is distinct from 'out'
     and (p_quantity is null or p_quantity > 0)
     and (p_expires_on is null or p_expires_on >= current_date - 3)
$$;


--
-- Name: people_jobs_today(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.people_jobs_today(p_household uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select u.jobs from public.household_usage u
                   where u.household_id = p_household and u.day = (now() at time zone 'utc')::date), 0)
$$;


--
-- Name: plan_recipe(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_recipe(p_recipe_id uuid, p_servings integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_household uuid := public.current_household_id();
  v_recipe public.recipes;
  v_servings int;
  v_up_next uuid;
  v_ing record;
  v_qty numeric;
  v_item public.grocery_items;
begin
  select * into v_recipe from public.recipes where id = p_recipe_id;
  if not found then
    raise exception 'recipe not found' using errcode = 'P0002';
  end if;

  v_servings := coalesce(p_servings,
                         (select default_servings from public.households where id = v_household),
                         v_recipe.servings);

  insert into public.up_next (household_id, recipe_id, servings)
  values (v_household, v_recipe.id, v_servings)
  returning id into v_up_next;

  for v_ing in
    select n.*, p.name_en as product_name, p.category as product_category
    from public.recipe_needs(v_recipe.id) n
    left join public.products p on p.id = n.product_id
    order by n.first_position
  loop
    continue when v_ing.product_id is not null and public.pantry_has(v_household, v_ing.product_id);
    v_qty := public.round_for_shopping(v_ing.quantity * v_servings / v_recipe.servings, v_ing.unit);
    v_item := public.add_grocery_item(
      coalesce(v_ing.product_name, v_ing.name),
      v_ing.product_id,
      v_qty,
      v_ing.unit,
      coalesce(v_ing.product_category, 'other'),
      'recipe'
    );
    insert into public.grocery_item_recipes (grocery_item_id, up_next_id, recipe_title, quantity, unit)
    values (v_item.id, v_up_next, v_recipe.title, v_qty, v_ing.unit)
    on conflict (grocery_item_id, up_next_id) do update
      set quantity = coalesce(public.grocery_item_recipes.quantity, 0) + coalesce(excluded.quantity, 0);
  end loop;

  return v_up_next;
end;
$$;


--
-- Name: queue_all_rereads(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_all_rereads(p_keep integer DEFAULT 15) RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  with used as (
    select household_id, count(*)::int as n
    from public.import_jobs
    where not public.is_background_kind(kind) and created_at > now() - interval '1 day'
    group by household_id
  ), wanted as (
    select r.id, r.household_id, r.title,
           row_number() over (partition by r.household_id order by r.updated_at desc, r.id) as rank
    from public.recipes r
    where exists (select 1 from public.recipe_ingredients i where i.recipe_id = r.id)
      -- Not one read again in the last hour (migration 22 just did some), nor one waiting.
      and not exists (select 1 from public.import_jobs j
                      where j.kind = 'reread' and j.subject_id = r.id
                        and (j.status in ('queued', 'processing') or j.created_at > now() - interval '1 hour'))
  ), queued as (
    insert into public.import_jobs (household_id, kind, subject_id, input_text, created_by)
    select w.household_id, 'reread', w.id, w.title, null
    from wanted w
    left join used u on u.household_id = w.household_id
    where w.rank <= 60 - greatest(p_keep, 0) - coalesce(u.n, 0)
    returning 1
  )
  select count(*)::int from queued
$$;


--
-- Name: queue_follow_checks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_follow_checks() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with queued as (
    insert into public.import_jobs (household_id, kind, input_text)
    select distinct f.household_id, 'follow_check', 'daily'
    from public.followed_creators f
    where not exists (
      select 1 from public.import_jobs j
      where j.household_id = f.household_id and j.kind = 'follow_check' and j.status in ('queued', 'processing')
    )
    returning 1
  )
  select count(*)::int from queued
$$;


--
-- Name: queue_for_you(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_for_you() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with queued as (
    insert into public.import_jobs (household_id, kind, input_text)
    select distinct r.household_id, 'for_you', 'weekly'
    from public.recipes r
    where not exists (
      select 1 from public.import_jobs j
      where j.household_id = r.household_id and j.kind = 'for_you' and j.status in ('queued', 'processing')
    )
    returning 1
  )
  select count(*)::int from queued
$$;


--
-- Name: queue_part_rereads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_part_rereads() RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  with queued as (
    insert into public.import_jobs (household_id, kind, subject_id, input_text, created_by)
    select r.household_id, 'reread', r.id, r.title, null
    from public.recipes r
    where (select count(*) from public.recipe_ingredients i where i.recipe_id = r.id) >= 6
      and not exists (select 1 from public.recipe_ingredients i where i.recipe_id = r.id and i.section is not null)
      and not exists (select 1 from public.import_jobs j
                      where j.kind = 'reread' and j.subject_id = r.id and j.status in ('queued', 'processing'))
    returning 1
  )
  select count(*)::int from queued
$$;


--
-- Name: queue_rereads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_rereads() RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  with used as (
    select household_id, count(*)::int as n
    from public.import_jobs
    where not public.is_background_kind(kind) and created_at > now() - interval '1 day'
    group by household_id
  ), wanted as (
    select r.id, r.household_id, r.title,
           row_number() over (partition by r.household_id order by r.updated_at desc, r.id) as rank
    from public.recipes r
    where exists (select 1 from public.recipe_ingredients i where i.recipe_id = r.id and i.product_id is null)
      and not exists (select 1 from public.import_jobs j
                      where j.kind = 'reread' and j.subject_id = r.id and j.status in ('queued', 'processing'))
  ), queued as (
    insert into public.import_jobs (household_id, kind, subject_id, input_text, created_by)
    select w.household_id, 'reread', w.id, w.title, null
    from wanted w
    left join used u on u.household_id = w.household_id
    where w.rank <= 60 - coalesce(u.n, 0)
    returning 1
  )
  select count(*)::int from queued
$$;


--
-- Name: queue_tidy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_tidy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_table_name = 'products' then
    if new.household_id is null or (new.family is not null and new.picto is not null) then
      return new;
    end if;
  elsif new.product_id is not null or new.category <> 'other' then
    return new;
  end if;
  -- One tidy waits per household: when it runs it takes everything waiting (apps/worker/src/tidy.ts).
  insert into public.import_jobs (household_id, kind, input_text)
  select new.household_id, 'tidy', 'everything waiting'
  where not exists (select 1 from public.import_jobs j
                    where j.household_id = new.household_id and j.kind = 'tidy' and j.status = 'queued');
  return new;
end;
$$;


--
-- Name: recipe_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recipe_coverage() RETURNS TABLE(recipe_id uuid, have_count integer, need_count integer, pantry_count integer, soon_names text[])
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select r.id,
         (count(*) filter (where x.at_home))::int,
         (count(*) filter (where not x.at_home))::int,
         (count(*) filter (where x.at_home and not x.always))::int,
         coalesce(array_agg(x.name_en order by x.soonest)
                    filter (where x.at_home and not x.always and x.soonest between current_date and public.use_soon_by()), '{}')
  from public.recipes r
  join lateral (
    select p.name_en,
           n.product_id is not null and public.pantry_has(r.household_id, n.product_id) as at_home,
           n.product_id is not null and public.is_always_have(r.household_id, n.product_id) as always,
           (select min(s.expires_on) from public.pantry_items s
            where s.household_id = r.household_id and s.product_id = n.product_id
              and public.pantry_row_at_home(s.level, s.quantity, s.expires_on)) as soonest
    from public.recipe_needs(r.id) n
    left join public.products p on p.id = n.product_id
  ) x on true
  where r.household_id = public.current_household_id()
  group by r.id
$$;


--
-- Name: recipe_needs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recipe_needs(p_recipe uuid) RETURNS TABLE(product_id uuid, name text, quantity numeric, unit text, first_position integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select (array_agg(i.product_id))[1],
         (array_agg(i.name order by i.position))[1],
         case when count(*) = count(i.quantity)
                   and count(distinct coalesce(nullif(i.unit, ''), 'unit')) = 1
              then sum(i.quantity) end,
         case when count(distinct coalesce(nullif(i.unit, ''), 'unit')) = 1 then min(i.unit) end,
         min(i.position)
  from public.recipe_ingredients i
  where i.recipe_id = p_recipe and not i.is_optional
  group by coalesce(i.product_id, i.id)
$$;


--
-- Name: ai_usage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_usage (
    day date NOT NULL,
    calls integer DEFAULT 0 NOT NULL,
    input_tokens bigint DEFAULT 0 NOT NULL,
    output_tokens bigint DEFAULT 0 NOT NULL
);


--
-- Name: record_ai_usage(integer, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_ai_usage(p_calls integer, p_input_tokens bigint, p_output_tokens bigint) RETURNS public.ai_usage
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  insert into public.ai_usage as u (day, calls, input_tokens, output_tokens)
  values ((now() at time zone 'utc')::date, greatest(p_calls, 0), greatest(p_input_tokens, 0), greatest(p_output_tokens, 0))
  on conflict (day) do update
    set calls = u.calls + excluded.calls,
        input_tokens = u.input_tokens + excluded.input_tokens,
        output_tokens = u.output_tokens + excluded.output_tokens
  returning u.*
$$;


--
-- Name: register_push_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_push_token(p_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_household uuid := public.current_household_id();
begin
  if v_household is null or p_token is null or length(trim(p_token)) = 0 then
    return;
  end if;
  insert into public.push_tokens (token, household_id, user_id)
  values (trim(p_token), v_household, auth.uid())
  on conflict (token) do update
    set household_id = excluded.household_id, user_id = excluded.user_id, created_at = now();
end;
$$;


--
-- Name: repair_heading_lines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_heading_lines() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_gone int;
begin
  with heads as (
    select i.id, i.recipe_id, i.position, public.heading_of(i.raw_text) as section
    from public.recipe_ingredients i
    where public.heading_of(i.raw_text) is not null
  ), placed as (
    select i.id,
           (select h.section from heads h
            where h.recipe_id = i.recipe_id and (h.position, h.id) < (i.position, i.id)
            order by h.position desc, h.id desc
            limit 1) as section
    from public.recipe_ingredients i
    where i.section is null
      and public.heading_of(i.raw_text) is null
      and exists (select 1 from heads h where h.recipe_id = i.recipe_id)
  )
  update public.recipe_ingredients i
    set section = p.section
    from placed p
    where i.id = p.id and p.section is not null;

  delete from public.recipe_ingredients where public.heading_of(raw_text) is not null;
  get diagnostics v_gone = row_count;
  return v_gone;
end;
$$;


--
-- Name: repair_vague_products(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_vague_products() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_line record;
  v_name text;
  v_product uuid;
  v_fixed int := 0;
begin
  for v_line in
    select i.id, i.raw_text, i.name, r.household_id, r.original
    from public.recipe_ingredients i
    join public.recipes r on r.id = i.recipe_id
    join public.products p on p.id = i.product_id
    where p.household_id is not null and public.is_vague_name(p.name_en)
  loop
    -- What the import read for this line, when it was specific.
    select btrim(o ->> 'name_en') into v_name
    from jsonb_array_elements(case when jsonb_typeof(v_line.original -> 'ingredients') = 'array'
                                   then v_line.original -> 'ingredients' else '[]'::jsonb end) o
    where o ->> 'raw_text' = v_line.raw_text and btrim(coalesce(o ->> 'name_en', '')) <> '' and not public.is_vague_name(o ->> 'name_en')
    limit 1;
    -- Else the line itself; a line that says nothing more ("1 tbsp sauce") keeps its word.
    v_name := coalesce(v_name, public.ingredient_label(v_line.raw_text), v_line.name);
    v_name := upper(left(v_name, 1)) || substr(v_name, 2);

    select p.id into v_product
    from public.products p
    where (p.household_id = v_line.household_id or p.household_id is null)
      and not public.is_vague_name(p.name_en)
      and (lower(p.name_en) = lower(v_name)
           or exists (select 1 from public.product_aliases a where a.product_id = p.id and a.alias = lower(v_name)))
    order by p.household_id nulls last, lower(p.name_en) = lower(v_name) desc
    limit 1;

    update public.recipe_ingredients set name = v_name, product_id = v_product where id = v_line.id;
    v_fixed := v_fixed + 1;
  end loop;

  delete from public.product_aliases a
  using public.products p
  where p.id = a.product_id and p.household_id is not null
    and (public.is_vague_name(p.name_en) or public.is_vague_name(a.alias));

  return v_fixed;
end;
$$;


--
-- Name: round_for_shopping(numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.round_for_shopping(p_quantity numeric, p_unit text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_quantity is null then null
    when p_unit is null or p_unit in ('unit', 'can', 'pack', 'bunch', 'clove', 'slice') then ceil(p_quantity)
    when p_unit in ('g', 'ml') then ceil(p_quantity)
    else round(p_quantity, 2)
  end
$$;


--
-- Name: save_imported_recipe(uuid, integer, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_imported_recipe(p_job uuid, p_attempt integer, p_recipe jsonb, p_ingredients jsonb, p_steps jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_job public.import_jobs;
  v_recipe uuid;
begin
  select * into v_job from public.import_jobs where id = p_job for update;
  if not found or v_job.status <> 'processing' or v_job.attempts <> p_attempt then
    raise exception 'job moved on' using errcode = 'P0004';
  end if;
  select r.id into v_recipe from public.recipes r where r.import_job_id = p_job and r.household_id = v_job.household_id;
  if found then
    return v_recipe;
  end if;

  insert into public.recipes (household_id, import_job_id, title, servings, total_minutes, source_url, source_platform,
                              image_path, source_author, source_channel_url, source_channel_id, original)
  select v_job.household_id, p_job, r.title, coalesce(r.servings, 4), r.total_minutes, r.source_url,
         coalesce(r.source_platform, 'other'), r.image_path, r.source_author, r.source_channel_url, r.source_channel_id, r.original
  from jsonb_populate_record(null::public.recipes, p_recipe) r
  returning id into v_recipe;

  insert into public.recipe_ingredients (recipe_id, position, raw_text, name, product_id, quantity, unit, is_guessed, is_optional, section)
  select v_recipe, x.position, x.raw_text, x.name, x.product_id, x.quantity, x.unit,
         coalesce(x.is_guessed, false), coalesce(x.is_optional, false), x.section
  from jsonb_populate_recordset(null::public.recipe_ingredients, coalesce(p_ingredients, '[]'::jsonb)) x;

  insert into public.recipe_steps (recipe_id, position, text, start_s)
  select v_recipe, x.position, x.text, x.start_s
  from jsonb_populate_recordset(null::public.recipe_steps, coalesce(p_steps, '[]'::jsonb)) x;

  return v_recipe;
end;
$$;


--
-- Name: set_always_have(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_always_have(p_product uuid, p_value boolean) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  insert into public.household_staples (household_id, product_id, always_have)
  values (public.current_household_id(), p_product, p_value)
  on conflict (household_id, product_id) do update set always_have = excluded.always_have
$$;


--
-- Name: set_pantry_item(uuid, public.pantry_level, public.zone, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_pantry_item(p_item uuid, p_level public.pantry_level DEFAULT NULL::public.pantry_level, p_zone public.zone DEFAULT NULL::public.zone, p_expires_on date DEFAULT NULL::date, p_clear_expiry boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_row public.pantry_items;
begin
  select * into v_row from public.pantry_items where id = p_item for update;
  if not found then
    raise exception 'pantry item not found' using errcode = 'P0002';
  end if;
  if p_level = 'out' then
    raise exception 'use pantry_out' using errcode = '22023';
  end if;

  if p_zone is not null and p_zone <> v_row.zone then
    if exists (select 1 from public.pantry_items
               where household_id = v_row.household_id and product_id = v_row.product_id and zone = p_zone) then
      v_row := public.pantry_put(v_row.household_id, v_row.product_id, p_zone, v_row.quantity, v_row.unit, v_row.expires_on, false);
      delete from public.pantry_items where id = p_item;
    else
      update public.pantry_items set zone = p_zone where id = p_item returning * into v_row;
    end if;
  end if;

  update public.pantry_items set
    level = coalesce(p_level, level),
    quantity = case when p_level is not null and p_level <> 'full' then null else quantity end,
    expires_on = case when p_clear_expiry then null else coalesce(p_expires_on, expires_on) end
  where id = v_row.id
  returning * into v_row;

  insert into public.pantry_events (household_id, product_id, label, delta, unit, reason, ref_id)
  select v_row.household_id, v_row.product_id, p.name_en, null, null, 'correction', v_row.id
  from public.products p where p.id = v_row.product_id;
  return v_row.id;
end;
$$;


--
-- Name: set_pantry_quantity(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_pantry_quantity(p_item uuid, p_quantity numeric, p_unit text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_before public.pantry_items;
  v_row public.pantry_items;
begin
  if p_quantity is not null and p_quantity <= 0 then
    raise exception 'use pantry_out' using errcode = '22023';
  end if;
  if not public.is_unit_code(p_unit) then
    raise exception 'unknown unit %', p_unit using errcode = '22023';
  end if;
  select * into v_before from public.pantry_items where id = p_item for update;
  if not found then
    raise exception 'pantry item not found' using errcode = 'P0002';
  end if;

  update public.pantry_items set
    quantity = p_quantity,
    unit = case when p_quantity is null then null else p_unit end,
    level = case when p_quantity is null then level else 'full' end,
    updated_at = now()
  where id = p_item
  returning * into v_row;

  insert into public.pantry_events (household_id, product_id, label, delta, unit, reason, ref_id)
  select v_row.household_id, v_row.product_id, p.name_en,
         case when v_before.quantity is not null and p_quantity is not null
                   and coalesce(v_before.unit, '') = coalesce(p_unit, '')
              then p_quantity - v_before.quantity end,
         p_unit, 'correction', v_row.id
  from public.products p where p.id = v_row.product_id;
  return v_row.id;
end;
$$;


--
-- Name: take_job_slot(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_job_slot(p_household uuid, p_day date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_jobs int;
  v_day date := (now() at time zone 'utc')::date;
begin
  if auth.uid() is not null then
    if p_household is distinct from public.current_household_id() then
      raise exception 'not your kitchen' using errcode = '42501';
    end if;
  elsif p_day is not null then
    v_day := p_day;
  end if;
  insert into public.household_usage as u (household_id, day, jobs)
  values (p_household, v_day, 1)
  on conflict (household_id, day) do update set jobs = u.jobs + 1
  returning u.jobs into v_jobs;
  if v_jobs > 60 then
    raise exception 'Too many imports today. Try again tomorrow.' using errcode = 'P0001';
  end if;
end;
$$;


--
-- Name: touch_products_of_aliases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_products_of_aliases() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    update public.products set updated_at = now() where id in (select distinct product_id from new_rows);
  elsif tg_op = 'UPDATE' then
    update public.products set updated_at = now()
      where id in (select product_id from new_rows union select product_id from old_rows);
  else
    update public.products set updated_at = now() where id in (select distinct product_id from old_rows);
  end if;
  return null;
end;
$$;


--
-- Name: touch_recipes_of_rows(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_recipes_of_rows() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    update public.recipes set updated_at = now() where id in (select distinct recipe_id from new_rows);
  elsif tg_op = 'UPDATE' then
    update public.recipes set updated_at = now()
      where id in (select recipe_id from new_rows union select recipe_id from old_rows);
  else
    -- A recipe deleted with its lines is gone already: nothing to touch.
    update public.recipes set updated_at = now() where id in (select distinct recipe_id from old_rows);
  end if;
  return null;
end;
$$;


--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: unplan(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unplan(p_up_next_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_link record;
begin
  for v_link in
    select l.*, g.status, g.quantity as item_quantity, g.unit as item_unit,
           (select count(*) from public.grocery_item_recipes o
             where o.grocery_item_id = l.grocery_item_id and o.up_next_id <> l.up_next_id) as other_links,
           g.source
    from public.grocery_item_recipes l
    join public.grocery_items g on g.id = l.grocery_item_id
    where l.up_next_id = p_up_next_id
  loop
    continue when v_link.status <> 'to_buy';
    if v_link.other_links = 0 and v_link.source = 'recipe' then
      delete from public.grocery_items where id = v_link.grocery_item_id;
    elsif v_link.quantity is not null and v_link.item_quantity is not null
          and coalesce(v_link.unit, '') = coalesce(v_link.item_unit, '') then
      update public.grocery_items
        set quantity = nullif(greatest(v_link.item_quantity - v_link.quantity, 0), 0),
            unit = case when v_link.item_quantity - v_link.quantity > 0 then unit end
        where id = v_link.grocery_item_id;
    end if;
  end loop;
  delete from public.up_next where id = p_up_next_id;
end;
$$;


--
-- Name: use_soon_by(); Type: FUNCTION; Schema: public; Owner: -
