--
-- Name: pantry_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pantry_status WITH (security_invoker='true') AS
 SELECT s.id,
    s.household_id,
    s.product_id,
    s.zone,
    s.quantity,
    s.unit,
    s.level,
    s.expires_on,
    s.updated_at,
    p.name_en,
    p.category,
    p.shelf_life_days,
    p.unit_family,
        CASE
            WHEN ((s.level = 'out'::public.pantry_level) OR (s.quantity = (0)::numeric)) THEN 'out'::text
            WHEN (s.expires_on IS NULL) THEN 'ok'::text
            WHEN (s.expires_on < (CURRENT_DATE - 3)) THEN 'gone'::text
            WHEN (s.expires_on < CURRENT_DATE) THEN 'check'::text
            WHEN (s.expires_on <= public.use_soon_by()) THEN 'soon'::text
            ELSE 'ok'::text
        END AS state,
    p.family,
    p.picto
   FROM (public.pantry_items s
     JOIN public.products p ON ((p.id = s.product_id)));


